const responseData = items[0].json;
let docContent = '';
let endpoints = [];
let authentication = {};
let servers = [];

// Response içeriğini al
if (typeof responseData === 'string') {
  docContent = responseData;
} else if (responseData.body) {
  docContent = responseData.body;
} else {
  docContent = JSON.stringify(responseData);
}

// OpenAPI/Swagger JSON formatı kontrolü
try {
  const jsonData = typeof responseData === 'object' ? responseData : JSON.parse(docContent);

  if (jsonData.openapi || jsonData.swagger) {
    const paths = jsonData.paths || {};

    for (const [path, methods] of Object.entries(paths)) {
      for (const [method, details] of Object.entries(methods)) {
        if (['get', 'post', 'put', 'patch', 'delete'].includes(method.toLowerCase())) {
          endpoints.push({
            path,
            method: method.toUpperCase(),
            summary: details.summary || '',
            operationId: details.operationId || '',
            parameters: details.parameters || [],
            requestBody: details.requestBody || null,
            responses: details.responses || {},
            tags: details.tags || []
          });
        }
      }
    }

    return [{
      json: {
        format: 'openapi',
        endpoints,
        components: jsonData.components || {},
        servers: jsonData.servers || [],
        authentication: jsonData.components?.securitySchemes || {},
        info: jsonData.info || {}
      }
    }];
  }
} catch (e) {
  // JSON parse hatası, HTML/text olarak devam et
}

// HTML/Text dokümantasyon parsing - daha güvenli regex kullanımı
const endpointPatterns = [
  /(GET|POST|PUT|PATCH|DELETE)\s+(\/[^\s<>\"\n\r]+)/gi,
  /(GET|POST|PUT|PATCH|DELETE):\s*(\/[^\s<>\"\n\r]+)/gi,
  /method[\s]*[=:]?[\s]*["']?(GET|POST|PUT|PATCH|DELETE)["']?[\s]+.*?["'](\/[^"'\s<>\n\r]+)["']/gi,
  /endpoint[\s]*[=:]?[\s]*["'](\/[^"'\s<>\n\r]+)["'][\s]+.*?(GET|POST|PUT|PATCH|DELETE)/gi
];

for (const pattern of endpointPatterns) {
  let match;
  // Regex exec kullanarak güvenli iteration
  while ((match = pattern.exec(docContent)) !== null) {
    if (match[1] && match[2]) {
      endpoints.push({
        method: match[1].toUpperCase(),
        path: match[2],
        source: 'regex'
      });
    } else if (match[2] && match[1]) {
      endpoints.push({
        method: match[2].toUpperCase(),
        path: match[1],
        source: 'regex'
      });
    }
  }
}

// Auth patterns arama
const authPatterns = [
  /api[_\s]*key/gi,
  /bearer[_\s]*token/gi,
  /basic[_\s]*auth/gi,
  /oauth/gi,
  /jwt/gi
];

for (const pattern of authPatterns) {
  if (pattern.test(docContent)) {
    authentication[pattern.source.replace(/[^a-zA-Z]/g, '')] = true;
  }
}

// Duplicate endpoint'leri temizle
const uniqueEndpoints = [];
const seen = new Set();

for (const endpoint of endpoints) {
  const key = `${endpoint.method}:${endpoint.path}`;
  if (!seen.has(key)) {
    seen.add(key);
    uniqueEndpoints.push(endpoint);
  }
}

return [{
  json: {
    format: 'parsed',
    endpoints: uniqueEndpoints,
    authentication,
    rawContent: docContent.substring(0, 1000), // İlk 1000 karakter
    endpointCount: uniqueEndpoints.length
  }
}];

const apiData = items[0].json;
const platformName = $node["Webhook Trigger"].json.body.platformName;

// Kategori endpoint'lerini tespit et
const categoryEndpoints = apiData.endpoints.filter(e => {
  const path = e.path.toLowerCase();
  return path.includes('category') || 
         path.includes('categories') ||
         path.includes('menu') ||
         path.includes('section') ||
         path.includes('catalog');
});

// Ürün endpoint'lerini tespit et
const productEndpoints = apiData.endpoints.filter(e => {
  const path = e.path.toLowerCase();
  return path.includes('product') || 
         path.includes('item') ||
         path.includes('menu-item') ||
         path.includes('dish') ||
         path.includes('article');
});

// Sipariş endpoint'lerini tespit et
const orderEndpoints = apiData.endpoints.filter(e => {
  const path = e.path.toLowerCase();
  return path.includes('order') || 
         path.includes('check') ||
         path.includes('purchase') ||
         path.includes('transaction') ||
         path.includes('sale');
});

return [{
  json: {
    platformName,
    categoryEndpoints,
    productEndpoints,
    orderEndpoints,
    authentication: apiData.authentication,
    servers: apiData.servers || []
  }
}];
